<script setup>
import { ref,onMounted } from 'vue'
import { api } from '../api'
defineEmits(['navigate'])
const today=ref({total:0,completed:0,pending:0}), medicines=ref([]),error=ref('')
onMounted(async()=>{try{[today.value,medicines.value]=await Promise.all([api('/today'),api('/medicines')])}catch(e){error.value=e.message}})
</script>
<template><p class="error" v-if="error">{{error}}</p><section class="hero"><div class="hero-top"><div><h2>今日用药 {{today.total}} 项</h2><p>{{today.pending?'还有 '+today.pending+' 项待确认，记得按时查看。':'今天暂无待确认的用药提醒。'}}</p></div><button class="expand" @click="$emit('navigate','提醒记录')">查看提醒 ›</button></div><div class="metrics"><div class="metric"><b>{{today.completed}}</b><span>已完成</span></div><div class="metric"><b>{{today.pending}}</b><span>待确认</span></div><div class="metric"><b>{{medicines.length}}</b><span>药箱药品</span></div></div></section><div class="section"><h3>快捷入口</h3></div><section class="quick"><button class="q" @click="$emit('navigate','扫一扫')"><i>📷</i><b>拍照识别</b><span>扫描药盒或说明书</span></button><button class="q" @click="$emit('navigate','药箱')"><i>🧰</i><b>家庭药箱</b><span>管理库存与有效期</span></button><button class="q" @click="$emit('navigate','提醒记录')"><i>⏰</i><b>服药提醒</b><span>查看并确认服药</span></button><button class="q" @click="$emit('navigate','用药知识')"><i>📖</i><b>用药知识</b><span>搜索药品、成分与来源</span></button></section><section class="quick" style="margin-top:10px"><button class="q" @click="$emit('navigate','AI助手')"><i>💬</i><b>AI 知识助手</b><span>知识咨询 · 多轮追问</span></button><button class="q" @click="$emit('navigate','风险报告')"><i>⚠️</i><b>用药风险</b><span>查看组合风险及依据</span></button></section></template>
